/* The 10 x 20 bitmap (r3mono_glyph row array) of a code point, or NULL. */
static inline const unsigned short *r3mono_find(unsigned int cp) {
    int lo = 0, hi = 4583 - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (r3mono_cp[mid] == cp) return r3mono_glyph[r3mono_idx[mid]];
        if (r3mono_cp[mid] < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}

